/**
 * Location Atlas (PoE 1) dataset schema. Generated by `scripts/poe1-campaign-data.mjs` from the game files
 * (RePoE export) and exile-leveling (MIT); never edited by hand — regenerate instead.
 */

export type AreaKind = "town" | "area";

/** How far a fact can be trusted; shown wherever the fact is shown. */
export type Confidence = "verified" | "community" | "partial" | "estimated" | "unverified" | "outdated";

export interface CampaignArea {
  /** Game area id as written in Client.txt (`Generating level N area "<id>"`). Stable key. */
  id: string;
  name: string;
  act: number;
  level: number;
  kind: AreaKind;
  waypoint: boolean;
  /** The act town this area belongs to. */
  town: string | null;
  /** Campaign areas reachable by walking (game data). */
  connections: string[];
  /** Connections to non-campaign content (Labyrinth, Sanctum, …). */
  otherConnections: string[];
  bossCount: number;
  actBossArea: boolean;
  /** The game's layout graph ids for this area; more than one = the layout varies. */
  topologies: string[];
  craftingRecipes: string[];
  /** Bosses named in the community route (exile-leveling). */
  bossNames?: string[];
}

export interface NavigationHint {
  /** Area the hint is about (where you are when it applies). */
  area: string;
  /** Area the step leads to, when the hint is about finding an exit. */
  toward?: string;
  /** The route step it belongs to (plain text). */
  step: string;
  text: string;
  /** Minimap direction in degrees, 0 = up, clockwise. */
  direction?: number;
  recommendedLevel?: number;
  /** Only in the league-start variant of the community route. */
  leagueStartOnly: boolean;
}

export interface CampaignQuest {
  id: string;
  name: string;
  act: number;
  npcs: string[];
}

export interface ActData {
  act: number;
  areas: CampaignArea[];
  hints: NavigationHint[];
  quests: CampaignQuest[];
}

export interface DataSource {
  id: string;
  name: string;
  url: string;
  author: string;
  license: string;
  type: "game-data" | "community" | "user";
  version: string | null;
  provides: string[];
  verification: Confidence;
}

export interface AtlasMeta {
  game: "poe1";
  patch: string;
  acts: number[];
  counts: { areas: number; hints: number; quests: number };
  sources: DataSource[];
}

export interface AtlasDataset {
  meta: AtlasMeta;
  acts: ActData[];
}
